// Runner around the upstream FlatBuffers benchmark object.
//
// Upstream measures benchmarks/cpp/flatbuffers/fb_bench.cpp through Google
// Benchmark (benchmarks/CMakeLists.txt), whose benchmark and gtest dependencies
// are fetched from GitHub at configure time.  The aarch64 performance Runner
// cannot rely on that download, so this case compiles the unmodified upstream
// benchmark source (fb_bench.cpp, with the header generated by the same pinned
// flatc) against the locally built flatbuffers library and drives its
// Encode/Decode/Use interface directly.
//
// The upstream benchmark always encodes the same small container, so it is a
// fixed-work micro benchmark: the runner executes `batches` independent batches
// of FLATBUFFERS_ITERATIONS iterations each, verifies the deterministic
// checksum of every batch, and reports the total encoded bytes.
#include <cstdint>
#include <cstdio>
#include <cstdlib>

#include "benchmarks/cpp/flatbuffers/fb_bench.h"

namespace {

constexpr int64_t kIterationsPerBatch = 10000;
// Deterministic checksum of one batch, computed from the pinned upstream
// source; a mismatch means the benchmark or the library changed behaviour.
constexpr int64_t kExpectedBatchChecksum = -7035620705617902304LL;

}  // namespace

int main(int argc, char **argv) {
  int64_t batches = 10;
  if (argc > 1) {
    batches = std::atoll(argv[1]);
  }
  if (batches <= 0) {
    std::fprintf(stderr, "batches must be positive\n");
    return 2;
  }

  int64_t encoded_bytes = 0;
  bool checksum_ok = true;
  for (int64_t batch = 0; batch < batches; ++batch) {
    auto bench = NewFlatBuffersBench(1024, nullptr);
    int64_t batch_checksum = 0;
    int64_t encoded_len = 0;
    for (int64_t i = 0; i < kIterationsPerBatch; ++i) {
      uint8_t *buffer = bench->Encode(nullptr, encoded_len);
      void *decoded = bench->Decode(buffer, encoded_len);
      batch_checksum += bench->Use(decoded);
      encoded_bytes += encoded_len;
    }
    if (batch_checksum != kExpectedBatchChecksum) checksum_ok = false;
  }

  std::printf(
      "[fb-bench] mode=upstream batches=%lld iterations=%lld encoded_bytes=%lld "
      "per_batch_checksum=%lld checksum_ok=%d\n",
      static_cast<long long>(batches),
      static_cast<long long>(kIterationsPerBatch),
      static_cast<long long>(encoded_bytes),
      static_cast<long long>(kExpectedBatchChecksum), checksum_ok ? 1 : 0);
  if (!checksum_ok) {
    std::fprintf(stderr, "upstream batch checksum mismatch\n");
    return 3;
  }
  return 0;
}
